import { Component, OnInit } from '@angular/core';
import { MisComprasService } from 'src/app/services/mis-compras.service';
import { MisCompras } from 'src/app/models/mis-compras';

@Component({
  selector: 'app-ej42',
  templateUrl: './ej42.component.html',
  styleUrls: ['./ej42.component.css']
})
export class Ej42Component implements OnInit{

  public productoMasCaro : {nombre : string, precio: number} | null = null;
  public clientes: string[] = [];


  constructor(private misComprasService: MisComprasService) { }

  ngOnInit(): void {
    this.cargarDatos();
  }


  cargarDatos(): void {
    this.misComprasService.obtenerCompras().subscribe(compras => {
      let maxPrecio = 0;
      // Identificar el producto más caro
      compras.forEach(compra => {
        compra.productos.forEach(producto => {
          if (producto.precio > maxPrecio) {
            maxPrecio = producto.precio;
            this.productoMasCaro = { nombre: producto.nombreProd, precio: producto.precio };
          }
        });
      });

      // Buscar todos los clientes que compraron ese producto
      if (this.productoMasCaro) {
        compras.forEach(compra => {
          compra.productos.forEach(producto => {
            if (producto.precio === this.productoMasCaro!.precio) {
              if (!this.clientes.includes(compra.emailUsuario)) {
                this.clientes.push(compra.emailUsuario);
              }
            }
          });
        });
      }
    });
  }

}
<div *ngIf="productoMasCaro">
  <h3>Producto más caro: {{ productoMasCaro.nombre }}</h3>
  <p>Precio: {{ productoMasCaro.precio | currency:'EUR' }}</p>
  <h4>Clientes que compraron este producto:</h4>
  <ul>
    <li *ngFor="let cliente of clientes">{{ cliente }}</li>
  </ul>
</div>
<div *ngIf="!productoMasCaro">
  <p>No hay datos de compras o no se encontró un producto más caro.</p>
</div>
